import UIKit

//  循环
func gcd(a a: Int, b: Int) -> Int {
    var x = a, y = b
    var n = x % y
    while n != 0 {
        x = y
        y = n
        n = x % y
    }
    return y
}

gcd(a: 75, b: 100)


