import UIKit

extension UIView {

    var rotationDegrees: CGFloat {
        get {
            let angleInRadians = atan2(transform.b, transform.a)
            return angleInRadians * 180.0 / CGFloat(M_PI)
        }
        set {
            transform = CGAffineTransform(rotationAngle: .pi / 180.0 * newValue)
        }
    }

}

