    }
    public override func main() {
        if isCancelled {
            Log.debug("canncelled")
            return
        }
        result = closure(self)
    }
    func resultSync() -> ResultType {
        if !isFinished {
            OperationQueue().addOperations([self], waitUntilFinished: true)
        }
        return result!
    }
