import Foundation

extension String {
  public func lines() -> [String] {
    var xs: [String] = []
    var line: String = ""
    // loop school
    for x in self {
      if x == "\n" {
        xs.append(line)
        line = ""
      } else {
        line += x
      }
    }
    if line != "" {
      xs.append(line)
    }
    return xs
  }

  public static func unlines(xs: [String]) -> String {
    return xs.reduce("", combine: { "\($0)\($1)\n" } )
  }

  public static func lines() -> Iso<String, String, [String], [String]> {
    return Iso(get: { $0.lines() }, inject: unlines)
  }
}

