    if let file = toFile {
        code = "set terminal png; set output \"\(file)\";" + plotCommand
    } else {
        code = plotCommand
    }

    let inputPipe = Pipe()
    var inputFile = inputPipe.fileHandleForWriting


    let gnuplot = Process()
